function normalIntervals(id,month=payMonth){const q=payroll(id,month),[a,b]=monthBounds(month);if(!q.plan)return [];let used=0;return state.journal.filter(j=>j.employee===id&&j.end>a&&j.start<b).slice().sort((x,y)=>x.start-y.start||x.end-y.end).map(j=>{const duration=j.end>j.start?j.duration/3600000*Math.max(0,Math.min(j.end,b)-Math.max(j.start,a))/(j.end-j.start):0,credited=Math.max(0,Math.min(duration,q.plan.hours-used));used+=duration;return {journal:j,hours:credited}}).filter(row=>row.hours>0.000000001)}
