function attributedCost(bid){const b=bmBy(bid);if(!b)return 0;return state.costs.reduce((sum,c)=>{let related=[];if(c.target===bid)return sum+c.amount;if(c.target.startsWith('PRF-'))related=state.bms.filter(x=>x.profiles.includes(c.target));if(c.target.startsWith('PRX-')){const ids=state.profiles.filter(p=>p.proxy===c.target).map(p=>p.id);related=state.bms.filter(x=>x.profiles.some(p=>ids.includes(p)))}return sum+(related.some(x=>x.id===bid)?c.amount/related.length:0)},0)}
