function farmSites(){const all=farmOwnSites(),q=search.toLowerCase(),list=all.filter(s=>(!filter||farmStatus(s)===filter)&&[s.company,s.data.cnpj,farmAddress(s),farmOwner(s.owner)].join(' ').toLowerCase().includes(q));return `<div class="bo-stats">${stat('Sites cadastrados',all.length,'Rascunhos e publicações')}${stat('Publicados',all.filter(s=>s.status==='ready'&&farmDomain(s.domain_id)?.active&&s.snapshot?.version===s.version).length,'HTTPS confirmado')}${stat('Rascunhos',all.filter(s=>!s.snapshot||s.snapshot.version!==s.version).length,'Aguardando preparação')}${stat('Domínios disponíveis',state.farm.domains.filter(d=>d.active&&(d.site_limit===null||farmDomainCount(d.id)<d.site_limit)).length,'Ativos · com capacidade')}</div>`+panel('Sites da operação',toolbar('Buscar empresa, CNPJ ou endereço',Array.from(new Set(all.map(farmStatus))))+(list.length?table(['Empresa / CNPJ','Endereço planejado','Responsável','Situação',''],list.map(s=>`<tr><td><strong>${esc(s.company)}</strong><small>${esc(s.data.cnpj)} · ${esc(farmThemes.find(t=>t.id===s.theme)?.name)}</small></td><td class="bo-farm-url">${esc(farmAddress(s))}<small>${s.publish_mode==='root'?'Domínio raiz':'Subdomínio'}${s.bm?' · '+esc(s.bm):''}</small></td><td>${esc(farmOwner(s.owner))}</td><td>${badge(farmStatus(s),s.status==='ready'?'green':'amber')}</td><td>${action('Abrir','farm-view:'+s.id)}</td></tr>`)):`<div class="bo-empty"><h3>${all.length?'Nenhum resultado':'Seu primeiro site começa aqui'}</h3><p style="margin:8px 0 16px">${all.length?'Ajuste a busca ou o filtro.':'Cadastre um domínio e crie o site da empresa pelo CNPJ.'}</p>${action('Domínios Farm','farm-tab:domains')}${action('Criar site','farm-new','bo-primary')}</div>`))}
function farmDomains(){const edit=state.farm.domains.find(d=>d.id===farmUI.domainEditing&&farmCanDomain(d));return panel(edit?'Editar domínio':'Adicionar domínio Farm',`<form class="bo-form bo-pad" data-form="farm-domain">${field('Domínio raiz','hostname',edit?.hostname||'','text',`required maxlength="253" placeholder="empresa.com.br" ${edit?'readonly':''}`)}${field('Limite de sites (vazio = ilimitado)','site_limit',edit?.site_limit??'','number','min="0" step="1" placeholder="Ilimitado"')}<div class="bo-full bo-sub">Zero bloqueia novos sites. Rascunhos também ocupam uma vaga. Use um domínio que pertença à sua operação.</div><div id="bo-error" class="bo-error bo-full" role="alert"></div><div class="bo-form-footer">${edit?action('Cancelar','farm-domain-cancel'):''}<button class="bo-action bo-primary" type="submit">${edit?'Salvar limite':'Cadastrar domínio'}</button></div></form>`)+state.farm.domains.map(d=>{const count=farmDomainCount(d.id),rootSite=state.farm.sites.find(s=>s.domain_id===d.id&&s.publish_mode==='root'&&s.snapshot),can=farmCanDomain(d);return panel(esc(d.hostname),`<div class="bo-pad"><div class="bo-farm-domain-summary"><div><strong>${count} / ${d.site_limit??'ilimitado'}</strong><p class="bo-sub">sites cadastrados · ${state.farm.sites.filter(s=>s.domain_id===d.id&&s.publish_mode==='subdomain').length} em subdomínios</p></div><div><strong>Raiz ${rootSite||d.rootOccupied?'ocupada':'livre'}</strong><p class="bo-sub">${rootSite?esc(rootSite.company):'Disponível para um site'}</p></div><div>${badge(d.active?'Disponível':'Inativo',d.active?'green':'amber')}<p class="bo-sub">Cloudflare: ${state.integrations?.cloudflare?'configurado':'aguardando conexão'}</p></div></div><div class="bo-row" style="margin-top:16px">${can?(state.farm.source==='cloudflare-d1'?action('Verificar domínio','farm-domain-verify:'+d.id):'')+action(d.active?'Desativar':'Ativar','farm-domain-toggle:'+d.id)+action('Editar limite','farm-domain-edit:'+d.id)+(count===0?action('Remover','farm-domain-delete:'+d.id,'bo-danger'):''):''}<span class="bo-sub">Cadastrado por ${esc(farmOwner(d.owner))}</span>${d.nameservers?.length?'<span class="bo-sub">Nameservers: '+d.nameservers.map(esc).join(' · ')+'</span>':''}${d.last_error?'<span class="bo-error">'+esc(d.last_error)+'</span>':''}</div></div>`)}).join('')+`<div class="bo-note">Para publicar, o domínio precisa estar ativo na conta Cloudflare conectada. Adicione a zona e configure os nameservers no painel Cloudflare antes de usar a publicação.</div>`}
function farmCapture(form){if(!form||form.dataset.form!=='farm-site')return;const values=Object.fromEntries(new FormData(form)),previous=farmUI.form||farmBlank();farmUI.form={...previous,...Object.fromEntries(['theme','publish_mode','subdomain','domain_id','head','owner','bm'].filter(k=>k in values).map(k=>[k,values[k]])),data:{...previous.data,...Object.fromEntries(Object.keys(previous.data).map(k=>[k,values[k]??previous.data[k]]))}}}
function farmEditor(){const f=farmUI.form??(farmUI.form=farmBlank()),opts=state.farm.domains.map(d=>[d.id,`${d.hostname} · ${farmDomainCount(d.id)}/${d.site_limit??'∞'}${!d.active?' · inativo':''}`]);return panel(f.id?'Editar site da empresa':'Criar site da empresa',`<form class="bo-form bo-pad" data-form="farm-site"><div class="bo-full bo-farm-step"><b>01</b><div><h3>Dados da empresa</h3><p class="bo-sub">Consulte o CNPJ e revise os dados antes de preparar o site.</p></div></div>${field('CNPJ','cnpj',f.data.cnpj,'text','required maxlength="18" placeholder="00.000.000/0000-00"')}<div class="bo-row" style="align-self:end">${action(farmUI.busy?'Consultando…':'Consultar CNPJ','farm-lookup','',farmUI.busy?'disabled':'')}</div>${[['razao','Razão social'],['fantasia','Nome fantasia'],['abertura','Data de abertura'],['atividade','Atividade principal'],['cidade','Cidade'],['uf','UF'],['telefone','Telefone / WhatsApp com DDD'],['email','E-mail']].map(([k,label])=>field(label,k,f.data[k],k==='email'?'email':'text',`${k==='razao'?'required':''} maxlength="${k==='uf'?2:k==='atividade'?500:200}"`)).join('')}<div class="bo-full bo-sub">${esc(f.source||'Preenchimento manual disponível.')}</div><div class="bo-full bo-farm-step"><b>02</b><div><h3>Modelo do site</h3><p class="bo-sub">Os 20 modelos originais da Farm.</p></div></div><div class="bo-full bo-farm-themes">${farmThemes.map((t,i)=>`<label class="bo-farm-theme ${f.theme===t.id?'selected':''}"><input type="radio" name="theme" value="${t.id}" ${f.theme===t.id?'checked':''} data-farm-change="theme"><span class="bo-farm-swatch" style="--swatch:${farmColors[i]}"><i></i><i></i><i></i></span><span>${String(i+1).padStart(2,'0')} · ${t.name}</span></label>`).join('')}</div><div class="bo-full bo-farm-step"><b>03</b><div><h3>Endereço e responsável</h3><p class="bo-sub">Escolha domínio raiz ou distribuição por subdomínio.</p></div></div>${select('Publicação','publish_mode',[['subdomain','Subdomínio'],['root','Domínio raiz']],f.publish_mode,'data-farm-change="mode"')}${select('Domínio Farm','domain_id',[[ '',f.publish_mode==='root'?'Selecione um domínio':'Automático — domínio com menos sites'],...opts],f.domain_id,f.publish_mode==='root'?'required':'')}${f.publish_mode==='subdomain'?field('Subdomínio','subdomain',f.subdomain,'text','maxlength="63" placeholder="nome-da-empresa"'):'<div class="bo-note">O domínio raiz recebe um único site por vez. A substituição exige confirmação.</div>'}${isAdmin()?select('Responsável','owner',[['ADMIN','Administrador'],...activePeople().map(p=>[p.id,p.name])],f.owner):`<div class="bo-note">Responsável: ${esc(person(employee))}</div>`}${select('BM vinculada (opcional)','bm',[['','Sem vínculo'],...ownBms().map(b=>[b.id,b.id+' · '+b.name])],f.bm)}<div class="bo-full bo-note" id="bo-farm-address">${esc(farmDraftAddress(f))}</div><details class="bo-full"><summary>HEAD personalizado</summary><label style="margin-top:10px">Código do HEAD<textarea name="head" maxlength="32000" spellcheck="false" placeholder="Meta tags de verificação">${esc(f.head)}</textarea></label><p class="bo-sub">Salvo no rascunho. O HEAD personalizado não é executado na pré-visualização.</p></details><div id="bo-error" class="bo-error bo-full" role="alert"></div><div class="bo-form-footer">${action('Pré-visualizar site','farm-preview')}<button class="bo-action" name="intent" value="draft" type="submit">Salvar rascunho</button><button class="bo-action bo-primary" name="intent" value="publish" type="submit">Salvar e publicar</button></div></form>`)+(farmUI.preview?panel('Pré-visualização do modelo',farmIframe(f.data,f.theme)):'')}
function farmDraftAddress(f){return f.domain_id?farmUrl({...f,subdomain:f.subdomain||farmSlug(f.data.fantasia||f.data.razao)||'empresa'},farmDomain(f.domain_id)||{hostname:'dominio.example'}):f.publish_mode==='root'?'Selecione o domínio raiz.':`https://${f.subdomain||farmSlug(f.data.fantasia||f.data.razao)||'empresa'}.[domínio automático]/`}
function farmIframe(data,theme){try{return `<iframe class="bo-farm-preview" title="Prévia do site da empresa" sandbox="" referrerpolicy="no-referrer" srcdoc="${esc(renderFarm(data,theme,''))}"></iframe>`}catch(e){return `<p class="bo-empty">${esc(e.message)}</p>`}}
function farmDetail(){const s=farmById(farmUI.view);if(!s){farmUI.view=null;return farmSites()}const logs=state.farm.history.filter(h=>h.site===s.id);return panel(esc(s.company),`<div class="bo-pad"><div class="bo-row" style="justify-content:space-between"><div><strong class="bo-farm-url">${esc(farmAddress(s))}</strong><p class="bo-sub">${esc(farmOwner(s.owner))} · ${esc(s.data.cnpj)} · versão ${s.version}</p></div>${badge(farmStatus(s),'amber')}</div><div class="bo-row" style="margin-top:18px">${action('← Sites','farm-tab:sites')}${farmCanEdit(s)?action('Editar site / HEAD','farm-edit:'+s.id)+action(s.snapshot?'Republicar':'Publicar','farm-publish:'+s.id,'bo-primary')+(s.status==='provisioning'?action('Verificar HTTPS','farm-verify:'+s.id):'')+(s.snapshot?action('Retirar publicação','farm-unpublish:'+s.id):'')+action('Excluir site','farm-delete:'+s.id,'bo-danger'):badge('Somente consulta')}${action('Baixar HTML','farm-download:'+s.id)}</div><p class="bo-sub" style="margin-top:12px">${s.last_error?'Última tentativa: '+esc(s.last_error)+'. ':''}Rascunhos e versões publicadas são separados.${s.snapshot?' A versão publicada é '+s.snapshot.version+'. Alterações no rascunho só entram após republicar.':''}</p></div>`)+panel('Prévia do rascunho · '+esc(farmThemes.find(t=>t.id===s.theme)?.name),farmIframe(s.data,s.theme))+(s.snapshot&&s.snapshot.version!==s.version?panel('Versão da última publicação',farmIframe(s.snapshot.data,s.snapshot.theme)):'')+panel('Histórico do site',`<div class="bo-pad">${logs.length?logs.map(h=>`<div class="bo-event"><span class="bo-dot"></span><div><p><strong>${esc(h.action)}</strong> · ${esc(h.message)}</p><small>${fmt(h.date)} · ${esc(h.who)}</small></div></div>`).join(''):'Nenhuma alteração registrada.'}</div>`)}
function farmValidate(f){const v=structuredClone(f);v.data.cnpj=normalizeCnpj(v.data.cnpj);for(const k of Object.keys(v.data))v.data[k]=String(v.data[k]||'').trim().slice(0,k==='atividade'?500:200);if(!v.data.razao)throw Error('Informe a razão social.');if(!farmThemes.some(t=>t.id===v.theme))throw Error('Escolha um modelo válido.');v.data.uf=v.data.uf.toUpperCase().slice(0,2);v.data.telefone=v.data.telefone.replace(/\D/g,'');if(!['root','subdomain'].includes(v.publish_mode))throw Error('Escolha um modo de publicação válido.');v.subdomain=v.publish_mode==='root'?null:(v.subdomain||farmSlug(v.data.fantasia||v.data.razao)).trim().toLowerCase();if(v.publish_mode==='subdomain'&&(!/^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/.test(v.subdomain)||['www','api','admin','mail','ftp'].includes(v.subdomain)))throw Error('Subdomínio inválido ou reservado.');if(v.publish_mode==='root'&&!v.domain_id)throw Error('Selecione um domínio para publicar na raiz.');if(v.head.length>32000)throw Error('O HEAD deve ter até 32.000 caracteres.');v.owner=isAdmin()?v.owner:employee;if(v.owner!=='ADMIN'&&!state.people.some(p=>p.id===v.owner))throw Error('Responsável inválido.');if(v.bm&&!ownBms().some(b=>b.id===v.bm))throw Error('BM indisponível para este acesso.');return v}
root.addEventListener('input',event=>{if(event.target.closest('[data-form="farm-site"]')){farmCapture(event.target.form);const address=root.querySelector('#bo-farm-address');if(address)address.textContent=farmDraftAddress(farmUI.form)}});
root.addEventListener('change',event=>{if(event.target.dataset.farmChange){farmCapture(event.target.form);farmUI.preview=false;render()}});

