function boIcon(name,extra=''){const path=boIconPaths[name]||boIconPaths.document;return `<svg class="bo-svg ${extra}" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">${path}</svg>`}
function boCleanLabel(label){return String(label).replace(/^(?:\+|←|▶|Ⅱ)\s*/,'').replace(/\s*→$/,'')}
function boActionIcon(cmd,label=''){const [name,id]=String(cmd||'').split(':');const exact={logout:'logout',reveal:label==='Ocultar'?'eyeOff':'eye',password:'key',start:'play',pause:'pause',end:'stop',confirm:'circleCheck','test-presence':'bell','test-timeout':'clock',adjust:'edit',receive:'circleCheck',pay:'money',sell:'sales',cancel:'close',back:'back',profile:'profile',bm:'business',task:label==='Reabrir'?'refresh':'check','farm-new':'plus','farm-view':'forward','farm-edit':'edit','farm-example':'document','farm-lookup':'search','farm-preview':'eye','farm-publish':'cloud','farm-verify':'shield','farm-download':'download','farm-delete':'trash','farm-domain-edit':'edit','farm-domain-toggle':label.startsWith('Desativar')?'pause':'play','farm-domain-delete':'trash','farm-domain-cancel':'close'};if(exact[name])return exact[name];if(name==='farm-tab')return id==='domains'?'network':id==='create'?'plus':'globe';if(name.startsWith('new-'))return 'plus';if(name.startsWith('edit-'))return 'edit';if(name.startsWith('go-'))return 'forward';if(/^(Salvar|Cadastrar|Adicionar|Atualizar)/.test(label))return label.includes('publicação')?'cloud':'save';if(label==='Entrar')return 'login';if(/^(Cancelar|Fechar)/.test(label))return 'close';if(label==='Concluir')return 'check';return null}
function boStatIcon(label){const t=String(label).toLowerCase();if(/domíni/.test(t))return 'network';if(/site|simula/.test(t))return 'globe';if(/rascunho/.test(t))return 'document';if(/hora|tempo/.test(t))return 'clock';if(/perfil|perfis/.test(t))return 'profile';if(/tarefa/.test(t))return 'tasks';if(/mão de obra|equipe/.test(t))return 'team';if(/manuten/.test(t))return 'tools';if(/recebi|receber/.test(t))return 'wallet';if(/venda|vendid/.test(t))return 'sales';if(/custo|gasto|aquisi/.test(t))return 'receipt';if(/paga|valor|mensal/.test(t))return 'money';if(/faixa|atingi/.test(t))return 'growth';if(/análise/.test(t))return 'search';if(/pront/.test(t))return 'circleCheck';if(/estoque/.test(t))return 'box';if(/criad|cadastrad|produ/.test(t))return 'business';return 'activity'}
function boPanelIcon(title){const t=String(title).toLowerCase();if(/atenção|alerta/.test(t))return 'warning';if(/histórico|trilha|movimenta/.test(t))return 'history';if(/credencia|senha/.test(t))return 'key';if(/jornada|sessão|intervalo|presença/.test(t))return 'clock';if(/equipe|funcionário/.test(t))return 'team';if(/domínio/.test(t))return 'network';if(/site|modelo|pré-visual/.test(t))return 'globe';if(/perfil/.test(t))return 'profile';if(/bm|capacidade|estoque/.test(t))return 'business';if(/venda/.test(t))return 'sales';if(/paga|remunera/.test(t))return 'wallet';if(/custo|gasto/.test(t))return 'receipt';if(/tarefa|trabalho|entrega/.test(t))return 'tasks';if(/configura|produção/.test(t))return 'settings';return 'document'}
function boDecorateButtons(){root.querySelectorAll('button').forEach(button=>{if(button.querySelector('svg')||button.classList.contains('bo-nav'))return;const raw=button.textContent.trim(),name=boActionIcon(button.dataset.action,raw);if(!name)return;const label=boCleanLabel(raw);button.innerHTML=boIcon(name)+`<span>${esc(label)}</span>`;button.classList.add('bo-has-icon')})}

function baseNavs(){return isAdmin()?[['dashboard','dashboard','Visão geral'],['profiles','profile','Perfis'],['bms','business','BMs'],['farm','globe','Farm de BMs'],['proxies','network','Proxies'],['sales','sales','Vendas de BMs'],['costs','receipt','Custos'],['team','team','Equipe e jornada'],['tasks','tasks','Tarefas'],['history','history','Histórico'],['settings','settings','Configurações']]:[['journey','clock','Minha jornada'],['payments','wallet','Meu pagamento'],['tasks','tasks','Minhas tarefas'],['profiles','profile','Meus perfis'],['bms','business','Minhas BMs'],['farm','globe','Farm de BMs']]}
function header(title,sub,actions=''){return `<div class="bo-heading"><div><h1>${title}</h1><p>${sub}</p></div><div class="bo-row">${actions}</div></div>`}
function periodSelect(){return `<select aria-label="Período do dashboard" data-change="period"><option value="today" ${period==='today'?'selected':''}>Hoje · ${fmt(DAY)}</option><option value="week" ${period==='week'?'selected':''}>Esta semana</option><option value="month" ${period==='month'?'selected':''}>${new Intl.DateTimeFormat('pt-BR',{month:'long',year:'numeric',timeZone:ZONE}).format(new Date(DAY+'T12:00:00Z'))}</option><option value="all" ${period==='all'?'selected':''}>Todo o histórico</option></select>`}
let shellUser='',lastBody='',menuOpen=false;
const mobileMenu=()=>globalThis.matchMedia?.('(max-width: 900px)').matches===true;
function setMenu(open,focus=true){
 menuOpen=open&&mobileMenu();root.classList?.toggle('bo-menu-open',menuOpen);
 const side=root.querySelector('.bo-side'),main=root.querySelector('.bo-main'),toggle=root.querySelector('[data-action="menu-open"]'),backdrop=root.querySelector('.bo-backdrop');
 if(side){side.inert=mobileMenu()&&!menuOpen;side.setAttribute('role',mobileMenu()?'dialog':'complementary');side.setAttribute('aria-label','Menu principal');if(menuOpen)side.setAttribute('aria-modal','true');else side.removeAttribute('aria-modal');}
 if(main)main.inert=menuOpen;if(toggle)toggle.setAttribute('aria-expanded',String(menuOpen));if(backdrop)backdrop.hidden=!menuOpen;
 if(document.body)document.body.style.overflow=menuOpen?'hidden':'';
 if(focus)(menuOpen?side?.querySelector('[data-action="menu-close"]'):toggle)?.focus();
}
document.addEventListener('keydown',ev=>{
 if(!menuOpen)return;if(ev.key==='Escape'){ev.preventDefault();setMenu(false);}
 if(ev.key==='Tab'){const buttons=[...root.querySelectorAll('.bo-side button:not([disabled])')],first=buttons[0],last=buttons.at(-1);if(ev.shiftKey&&document.activeElement===first){ev.preventDefault();last?.focus();}else if(!buttons.includes(document.activeElement)||(!ev.shiftKey&&document.activeElement===last)){ev.preventDefault();first?.focus();}}
});
globalThis.addEventListener?.('resize',()=>setMenu(menuOpen,false));
function render(){
 if(!role){shellUser='';lastBody='';setMenu(false,false);root.innerHTML=loginScreen();boDecorateButtons();return;}
 if(!navs().some(n=>n[0]===page))page=isAdmin()?'dashboard':'journey';
 const content=editor?renderEditor():detail?renderDetail():({dashboard,profiles,bms,proxies,sales,costs,team,tasks,history,settings,journey,payments,farm,account:accountScreen}[page])();
 const body=(notice?`<div class="bo-toast" role="status">${esc(notice)}</div>`:'')+(!isAdmin()&&page!=='journey'?checkpoint():'')+content;
 const user=role+':'+employee+':'+currentName(),title=navs().find(n=>n[0]===page)?.[2]||'Visão geral';
 if(shellUser!==user||!root.querySelector('.bo-body')){
  shellUser=user;lastBody=body;
  root.innerHTML=`<div class="bo-shell"><button class="bo-backdrop" data-action="menu-close" aria-label="Fechar menu" tabindex="-1" hidden></button><aside id="bo-sidebar" class="bo-side"><div class="bo-brand"><span class="bo-logo">B</span><div><b>Big Operação</b><small>Gestão operacional</small></div><button class="bo-menu-close" data-action="menu-close" aria-label="Fechar menu">×</button></div><div class="bo-nav-scroll"><div class="bo-nav-label">${isAdmin()?'WORKSPACE':'ÁREA DO FUNCIONÁRIO'}</div><nav aria-label="Navegação principal">${navs().map(n=>`<button class="bo-nav ${page===n[0]?'active':''}" data-page="${n[0]}" aria-current="${page===n[0]?'page':'false'}"><span class="bo-icon">${boIcon(n[1])}</span>${n[2]}</button>`).join('')}</nav></div><div class="bo-side-bottom"><span class="bo-avatar">${isAdmin()?'AD':esc(person(employee).split(' ').map(x=>x[0]).slice(0,2).join(''))}</span><div class="bo-account-name"><strong>${esc(currentName().split(' ')[0])}</strong><small>${isAdmin()?'Administrador':'Funcionário'}</small></div>${action('Sair','logout','bo-quiet')}</div></aside><main class="bo-main"><div class="bo-top"><div class="bo-top-title"><button class="bo-menu-toggle" data-action="menu-open" aria-label="Abrir menu" aria-controls="bo-sidebar" aria-expanded="false"><svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M4 6h16M4 12h16M4 18h16"/></svg></button><span class="bo-breadcrumb">${esc(title)}</span></div><span class="bo-top-date">${fmt(DAY)}</span></div><div class="bo-sync-error" role="status" hidden></div><div class="bo-body">${body}</div><footer class="bo-footer">Big Operação · Gestão operacional</footer></main></div>`;
  setMenu(false,false);
 }else{
  for(const button of root.querySelectorAll('[data-page]')){button.classList.toggle('active',button.dataset.page===page);button.setAttribute('aria-current',button.dataset.page===page?'page':'false');}
  root.querySelector('.bo-breadcrumb').textContent=title;root.querySelector('.bo-top-date').textContent=fmt(DAY);
  if(lastBody!==body){const el=root.querySelector('.bo-body'),focused=document.activeElement,scrolls=[...el.querySelectorAll('.bo-table-wrap')].map(n=>n.scrollLeft);el.innerHTML=body;lastBody=body;el.querySelectorAll('.bo-table-wrap').forEach((n,i)=>n.scrollLeft=scrolls[i]||0);if(focused?.dataset?.input==='search'){const input=el.querySelector('[data-input="search"]');input?.focus();input?.setSelectionRange(focused.selectionStart,focused.selectionEnd);}}
 }
 boDecorateButtons();tickDisplay();
}
function connectionError(message=''){const el=root.querySelector('.bo-sync-error');if(el){el.hidden=!message;el.textContent=message;}}

function dashboard(){const sold=state.sales.filter(s=>inPeriod(s.date)),total=sold.reduce((a,s)=>a+s.amount,0),paid=sold.filter(s=>s.paid).reduce((a,s)=>a+s.amount,0),spent=state.costs.filter(c=>c.paid&&inPeriod(c.date)).reduce((a,c)=>a+c.amount,0),stuck=state.bms.filter(b=>b.capacity===250&&dayDiff(b.capacitySince)>=state.settings.stuck&&b.stock!=='Vendida'),ready=state.bms.filter(available),renewing=state.proxies.filter(p=>(Date.parse(p.renewal)-Date.parse(DAY))/86400000<=7),types=['Ativa','Em análise','Em preparação','Restrita','Desativada'];return header('Sua operação, em um só lugar','Estoque atual, produção e resultado das vendas.',periodSelect()+action('+ Registrar venda','new-sale','bo-primary'))+`<div class="bo-stats">${stat('BMs em estoque',state.bms.filter(b=>b.stock!=='Vendida').length,`${state.bms.length} cadastradas · ${state.sales.length} vendidas`)}${stat('Prontas para uso',ready.length,'Ativas e disponíveis agora')}${stat('Vendas de BMs',money(total),`${sold.length} vendas no período`,true)}${stat('Valores recebidos',money(paid),`${money(total-paid)} a receber`)}</div><div class="bo-grid">${panel('Situação atual das BMs',`<div class="bo-pad">${types.map(t=>{const n=state.bms.filter(b=>b.status===t&&b.stock!=='Vendida').length;return `<div class="bo-bar-row"><span>${t}</span><div class="bo-bar-track"><div class="bo-bar-fill" style="width:${n/Math.max(1,state.bms.filter(b=>b.stock!=='Vendida').length)*100}%"></div></div><b>${n}</b></div>`}).join('')}<div class="bo-sub">Estoque sem as BMs já vendidas.</div></div>`,badge('Estoque atual'))}${panel('Vendas nos últimos 7 dias',salesChart(),action('Ver vendas →','go-sales','bo-quiet'))}</div><div class="bo-stats">${stat('BMs em análise',state.bms.filter(b=>b.status==='Em análise'&&b.stock!=='Vendida').length,'Estoque atual')}${stat('Perfis ativos',state.profiles.filter(p=>p.status==='Ativo').length,'Perfis da operação')}${stat('Criadas na semana',state.bms.filter(b=>b.created>=weekStart()&&b.created<=DAY).length,'Criação real · semana atual')}${stat('Gastos pagos',money(spent),'No período selecionado')}</div><div class="bo-stats" style="grid-template-columns:repeat(2,minmax(0,1fr))">${stat('Atingiram a faixa 2K',new Set(state.events.filter(e=>e.type==='Capacidade'&&e.text.endsWith('2K')&&inPeriod(e.date)).map(e=>e.entity)).size,'BMs únicas · no período selecionado')}${stat('Cadastradas no período',state.bms.filter(b=>inPeriod(b.registered)).length,'Inclui BMs que já existiam')}</div>${capacitySummary()}<div class="bo-stats" style="grid-template-columns:repeat(2,minmax(0,1fr))">${stat('Mão de obra estimada',laborPeriodLabel(),'Valor normal + extras · período selecionado')}${stat('Mão de obra nas vendas',money(sold.reduce((sum,s)=>sum+bmLabor(s.bm),0)),sold.some(s=>!bmLaborKnown(s.bm))?'Estimativa parcial · há BMs sem configuração':'Rateio do mês de criação · estimativa')}</div>${panel('Atenção na operação',`<div class="bo-pad">${stuck.map(b=>`<div class="bo-list-row"><div><p><strong>${esc(b.id)}</strong> está em 250 há ${dayDiff(b.capacitySince)} dias</p><span class="bo-sub">${esc(b.name)} · ${esc(person(b.owner))}</span></div>${action('Conferir','bm:'+b.id,'bo-quiet')}</div>`).join('')||'<p class="bo-sub">Nenhuma BM ultrapassou o prazo configurado.</p>'}${renewing.map(p=>`<div class="bo-list-row"><div><p>${esc(p.name)} · renovação ${p.renewal<DAY?'em atraso':'próxima'}</p><span class="bo-sub">${p.id} · ${fmt(p.renewal)}</span></div>${action('Ver proxies','go-proxies','bo-quiet')}</div>`).join('')}</div>`,badge(`${stuck.length+renewing.length} alertas`,'amber'))}${panel('Movimentações recentes',eventList(state.events.slice(0,5)),action('Histórico completo →','go-history','bo-quiet'))}`}
function capacitySummary(){return panel('Estoque por faixa de capacidade',`<div class="bo-pad bo-capacity-grid">${CAPACITIES.filter(([v])=>v!==0).map(([value,label])=>`<div><span class="bo-sub">${label}</span><div class="bo-stat-value">${state.bms.filter(b=>b.capacity===value&&b.stock!=='Vendida').length}</div></div>`).join('')}</div>`,badge('BMs não vendidas'))}
function salesChart(){const dates=Array.from({length:7},(_,i)=>{const d=new Date(DAY+'T12:00:00Z');d.setUTCDate(d.getUTCDate()-6+i);return d.toISOString().slice(0,10)}),vals=dates.map(d=>state.sales.filter(s=>s.date===d).reduce((a,s)=>a+s.amount,0)),max=Math.max(1,...vals);return `<div class="bo-pad"><p class="bo-sub">Valor vendido (R$) · inclui recebimentos pendentes</p><div class="bo-bars" role="img" aria-label="Vendas diárias em reais: ${vals.join(', ')}">${dates.map((d,i)=>`<div class="bo-bar-col"><span class="bo-bar-amount">${vals[i]?vals[i].toLocaleString('pt-BR'):'—'}</span><div class="bo-sales-bar" style="height:${Math.max(2,vals[i]/max*82)}px"></div><span>${d.slice(8)}/${d.slice(5,7)}</span></div>`).join('')}</div></div>`}
function toolbar(placeholder,options=[]){return `<div class="bo-toolbar"><input aria-label="${placeholder}" data-input="search" placeholder="${placeholder}" value="${esc(search)}">${options.length?`<select aria-label="Filtrar registros" data-change="filter"><option value="">Todas as opções</option>${options.map(o=>`<option ${filter===o?'selected':''}>${o}</option>`).join('')}</select>`:''}</div>`}
function profiles(){const list=ownProfiles().filter(p=>(p.id+' '+p.name).toLowerCase().includes(search.toLowerCase())&&(!filter||p.status===filter));return header(isAdmin()?'Perfis':'Meus perfis','Acessos organizados e BMs vinculadas, sem duplicidade.',action('+ Novo perfil','new-profile','bo-primary'))+panel('Perfis cadastrados',toolbar('Buscar perfil ou código',['Ativo','Em revisão','Desativado'])+table(['Perfil','Situação','BMs vinculadas','Responsável',''],list.map(p=>`<tr><td><button class="bo-cell-link" data-action="profile:${p.id}">${esc(p.name)}</button><small>${p.id}</small></td><td>${badge(p.status)}</td><td>${state.bms.filter(b=>b.profiles.includes(p.id)).length} BMs</td><td>${esc(person(p.owner).split(' ')[0])}</td><td>${action('Abrir →','profile:'+p.id,'bo-quiet')}</td></tr>`)))}
